import{_ as t,o as a,c as r,a5 as o}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Repository — Implementation document set","description":"","frontmatter":{},"headers":[],"relativePath":"feature/repository/README.md","filePath":"feature/repository/README.md"}'),i={name:"feature/repository/README.md"};function d(s,e,n,l,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="repository-—-implementation-document-set" tabindex="-1">Repository — Implementation document set <a class="header-anchor" href="#repository-—-implementation-document-set" aria-label="Permalink to &quot;Repository — Implementation document set&quot;">​</a></h1><p><strong>Trạng thái:</strong> chuẩn bị tài liệu hoàn tất; chưa implement/chưa chạy tests/migrations/provider probes. Business authority: <a href="./../../../../tuan-research/REPOSITORY_SPEC.html">BR01–BR25</a>. Mỗi FR có đúng4file spec→plan→task→test, phải đọc đủ trước code. Ticket local map bên dưới; không Jira issue nào được tạo. Spec per-FR đã đồng bộ planning contract, không coi ví dụ numeric ErrorCode hoặc class mới trong source spec là code đã có.</p><table tabindex="0"><thead><tr><th>Order</th><th>FR</th><th>Spec</th><th>Plan</th><th>Task</th><th>Test</th><th>Implementation blocker</th></tr></thead><tbody><tr><td>01</td><td>3.6.12 Add</td><td><a href="./add-material-repository/spec.html">spec</a></td><td><a href="./add-material-repository/plan.html">plan</a></td><td><a href="./add-material-repository/task.html">task</a></td><td><a href="./add-material-repository/test.html">test</a></td><td>G0 storage + G1 ledger trước enable writes</td></tr><tr><td>02</td><td>3.6.11 View</td><td><a href="./view-material-repository/spec.html">spec</a></td><td><a href="./view-material-repository/plan.html">plan</a></td><td><a href="./view-material-repository/task.html">task</a></td><td><a href="./view-material-repository/test.html">test</a></td><td>Add foundation ready</td></tr><tr><td>03</td><td>3.6.13 Update</td><td><a href="./update-material-repository/spec.html">spec</a></td><td><a href="./update-material-repository/plan.html">plan</a></td><td><a href="./update-material-repository/task.html">task</a></td><td><a href="./update-material-repository/test.html">test</a></td><td>Add+View; shared lineage lease/revision</td></tr><tr><td>04</td><td>3.6.14 Remove</td><td><a href="./remove-material-repository/spec.html">spec</a></td><td><a href="./remove-material-repository/plan.html">plan</a></td><td><a href="./remove-material-repository/task.html">task</a></td><td><a href="./remove-material-repository/test.html">test</a></td><td>Add+View; reference inventory trước purge</td></tr><tr><td>05</td><td>3.6.16 Download</td><td><a href="./download-material/spec.html">spec</a></td><td><a href="./download-material/plan.html">plan</a></td><td><a href="./download-material/task.html">task</a></td><td><a href="./download-material/test.html">test</a></td><td>Add+View; actual private provider + durable audit</td></tr></tbody></table><h2 id="shared-ownership-va-contract" tabindex="-1">Shared ownership và contract <a class="header-anchor" href="#shared-ownership-va-contract" aria-label="Permalink to &quot;Shared ownership và contract&quot;">​</a></h2><p>Add owns storage router/options/validator, scoped actor policy, mutation lease/fence/root revision/reference pins, upload saga, PG quota ledger/reservations/physical pool accounting, session/Material migration, trusted private reader/watermark compatibility. Các FR khác chỉ extend/call shared helpers. Không thêm Repository microservice, Mongo metadata mirror, Redis ACL/list/URL cache hoặc USER_GDRIVE connector trong MVP.</p><p>Canonical providers SYSTEM_GDRIVE/SYSTEM_S3/USER_GDRIVE (last disabled); Material upload status UPLOADING/VALIDATING/READY/REJECTED/FAILED. Soft deletion uses deleted_at, purge_state separate. page/size+array data/meta; no preview public fallback; no claim S3-compatible100%. Quota total catalog, BASIC20GiB, expired read/update/delete/restore/download allowed; trash charged, release only confirmed purge, no double count staging+canonical logical usage.</p><h2 id="gates-chua-thuc-hien" tabindex="-1">Gates chưa thực hiện <a class="header-anchor" href="#gates-chua-thuc-hien" aria-label="Permalink to &quot;Gates chưa thực hiện&quot;">​</a></h2><ul><li>G0: pinned rclone/private AWS test endpoints, presign/HEAD/Range/conditional copy, metadata/attachment/durable cache restart, throttling and capacity proof.</li><li>G1: PG ledger/reservation+Mongo saga fault injection, lock order, retry/idempotency, session expiry vs VALIDATING claim, pool overhead after PUT expiry.</li><li>Purge gate: complete reference-writer inventory/backfill, durable pin+claim serialization, crash replay storage delete→PG release→Mongo complete, versioned object retention proof.</li><li>UI/integration: gateway subscription filter, Mobile legacy sessions/DTO paths, vi/en, dark/light/keyboard/responsive và all stale workspace response guards.</li></ul><p>Gates là checklist thực thi, không lý do dừng chuẩn bị tài liệu. Không có credentials/ endpoint test thì ghi NOT RUN, không dùng mock thay external proof hoặc enable production. Rollback disable new writer/purge flags, reconcile pending operations, giữ ledger/metadata, không tự xóa DB, quay public ACL hay đổi quyết định BASIC overflow.</p><p>Specs trước normalization được giữ ở <code>.scratch/repository/spec-before-planning/</code> ngoài repo infrastructure để đối chiếu, không là tài liệu active hoặc một bản spec cạnh tranh.</p><h2 id="customer-owned-drive-storage" tabindex="-1">Customer-owned Drive storage <a class="header-anchor" href="#customer-owned-drive-storage" aria-label="Permalink to &quot;Customer-owned Drive storage&quot;">​</a></h2><p>The customer-drive-overflow feature adds Owner/Manager OAuth connection, private brandhub-[agency]/workspace_N folders, Drive-first material writes and active-paid-plan S3 overflow. USER_GDRIVE is enabled only by the explicit customer-drive feature gate; SYSTEM_GDRIVE remains a historical system-provider route. See <a href="./customer-drive-overflow/plan.html">customer-drive-overflow/plan.md</a> for staged schema, account-wide capacity reservations, private gateway streaming and rollout prerequisites.</p>',12)])])}const u=t(i,[["render",d]]);export{m as __pageData,u as default};
